const {chromium}=require('playwright');const fs=require('fs');const serverChromium=require('/tmp/h-earth-browser/node_modules/@sparticuz/chromium/build/index.js').default;
(async()=>{const http=require('http'),path=require('path');const root='/tmp/h-earth-traversal-repo';const server=http.createServer((req,res)=>{let name=decodeURIComponent(new URL(req.url,'http://localhost').pathname);if(name.endsWith('/'))name+='index.html';const file=path.join(root,name);try{const data=fs.readFileSync(file);res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.html')?'text/html':file.endsWith('.css')?'text/css':file.endsWith('.json')?'application/json':'application/octet-stream');res.end(data)}catch{res.statusCode=404;res.end('Not found')}});await new Promise(r=>server.listen(8766,'127.0.0.1',r));const browser=await chromium.launch({executablePath:await serverChromium.executablePath(),headless:true,args:[...serverChromium.args,'--enable-unsafe-swiftshader']});const page=await browser.newPage({viewport:{width:384,height:688},deviceScaleFactor:1});const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:8766/showroom/globe/h-earth/?visual=terrain-relief-v2&performance=1',{waitUntil:'domcontentloaded',timeout:120000});
await page.waitForFunction(()=>window.H_EARTH_RUN8E_PUBLIC_ROUTE?.ready,null,{timeout:120000});
await page.waitForSelector('.h-earth-experience-loader',{state:'hidden',timeout:120000});
const start=await page.evaluate(()=>window.H_EARTH_RUN8E_PUBLIC_ROUTE.getIntakeReceipt().currentNavigationState.position);
const travel=async(deltaY)=>page.evaluate(y=>{const c=document.querySelector('canvas');c.dispatchEvent(new WheelEvent('wheel',{deltaY:y,bubbles:true,cancelable:true}));},deltaY);
for(let i=0;i<30;i++)await travel(-700);await travel(-280);await travel(-350);
await page.waitForFunction(()=>document.getElementById('h-earth-navigation-boundary')?.hidden===false);
const boundary=await page.evaluate(()=>{const api=window.H_EARTH_RUN8E_PUBLIC_ROUTE;const n=document.getElementById('h-earth-navigation-boundary');const r=api.getIntakeReceipt();return {position:r.currentNavigationState.position,message:n.textContent,hidden:n.hidden,lastProposal:r.proposals.at(-1),rect:n.getBoundingClientRect().toJSON(),role:n.getAttribute('role'),live:n.getAttribute('aria-live'),gpu:api.getLiveGpuReceipt()};});
await page.screenshot({path:'/tmp/traversal-boundary-mobile.png'});
await travel(350);await page.waitForFunction(()=>document.getElementById('h-earth-navigation-boundary').hidden);
const retreat=await page.evaluate(()=>({position:window.H_EARTH_RUN8E_PUBLIC_ROUTE.getIntakeReceipt().currentNavigationState.position,hidden:document.getElementById('h-earth-navigation-boundary').hidden}));
const report={start,boundary,retreat,errors};fs.writeFileSync('/tmp/traversal-browser-evidence.json',JSON.stringify(report,null,2));console.log(JSON.stringify({start,boundary:{position:boundary.position,message:boundary.message,visible:!boundary.hidden,rect:boundary.rect},retreat,errors}));await browser.close();server.close();})().catch(e=>{console.error(e);process.exit(1)});
